package core

import (
	"github.com/jokruger/kavun/core/member"
	"github.com/jokruger/kavun/internal/text"
)

// byte's members: one function per member, each declared by the //kavun:member directive in its doc comment. The table,
// byteMethods, and the member entries of docs/reference/types/byte.md (alphabetical, so the order here is free) are
// generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Render the value per the [format mini-language](../../format_mini_language.md).
//
// `format()` is the render, total on every octet; it shows the *number*, and the symbol spelling is the `c`
// verb:
//
// ```go
// b'A'.format()       // => "65" — default verb is d, always works
// byte(200).format()  // => "200"
// f"{b'A'}"           // => "65" — an f-string is a render, not a conversion
// format(b'A')        // => "65"
// b'A'.format("c")    // => "A" — ASCII character rendering
// b'A'.format("q")    // => "'A'" — quoted literal
// b'A'.format("x")    // => "0x41"
// b'A'.format("b")    // => "0b1000001"
// ```
//
// `.string()` answers "what text is this?" (the symbol, or the octet's escape); `format()` answers "render this
// value" (the number). Both exist because they are different questions.
//
//kavun:member format pure ([spec]) -> string
func byteFormat(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return FormatWithSpec(v, id, args)
}

// Report truthiness: the zero octet is falsy (`!!x` ⟺ `x != byte()`).
//
// ```go
// b'\x00'.is_true()   // => false
// b'A'.is_true()      // => true
// !!b'\x00'           // => false
// ```
//
//kavun:member is_true pure () -> bool
func byteIsTrue(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	t, err := ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return Undefined, err
	}
	return BoolValue(t), nil
}

// Answer the receiver — a `byte` is always immutable.
//
// Identity no-ops on an immutable scalar — kept so generic code never type-errors:
//
// ```go
// b'A'.copy()     // => byte(65)
// b'A'.freeze()   // => byte(65)
// ```
//
//kavun:member copy pure () -> byte
func byteCopy(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the receiver — a `byte` is always immutable; see [`copy`](#copy).
//
//kavun:member freeze pure () -> byte
func byteFreeze(_ VM, v Value, _ member.ID, _ []Value) (Value, error) {
	return v, nil
}

// Answer the receiver, the identity conversion.
//
//kavun:member byte pure ([default]) -> byte
func byteByte(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), byteTypeName, args, true, v)
}

// Answer the octet's value, 0–255.
//
// ```go
// b'A'.int()             // => 65
// byte(200).int()        // => 200 — total, the numeric reading always exists
// ```
//
//kavun:member int pure ([default]) -> int
func byteInt(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	i, ok := v.AsInt()
	return ConvMember(id.String(), byteTypeName, args, ok, IntValue(i))
}

// Convert to the same symbol as a `rune`; above `0x7F` it raises unless a default is given.
//
// ```go
// b'A'.rune()            // => 'A'
// byte(200).rune()       // Error: conversion: cannot convert byte to rune
// byte(200).rune('?')    // => '?' — the default covers the partial edge
// ```
//
//kavun:member rune pure ([default]) -> rune
func byteRune(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	c, ok := v.AsRune()
	return ConvMember(id.String(), byteTypeName, args, ok, RuneValue(c))
}

// Answer the one-octet text holding the byte: its symbol in ASCII, the octet's escape above.
//
// ```go
// b'A'.string()          // => "A" — the SYMBOL, not the number
// byte(200).string()     // => "\xc8" — the octet's escape; .bytes() gives bytes([200]) back
// byte(200).string("?")  // => "\xc8" — total, so the default is never used
// ```
//
//kavun:member string pure ([default]) -> string
func byteString(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	// TOTAL: a byte always has text content — its ASCII symbol below 0x80, and above it the
	// one-octet text that decodes to this octet's escape. The render is unmoved: b'A'.format() -> "65"
	return ConvMember(id.String(), byteTypeName, args, true, NewStringValue(string([]byte{byte(v.Data)})))
}

// Answer the one-octet text holding the byte, as `runes`; see [`string`](#string).
//
// ```go
// b'A'.runes()           // => u"A"
// ```
//
//kavun:member runes pure ([default]) -> runes
func byteRunes(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return ConvMember(id.String(), byteTypeName, args, true, NewRunesValue(text.DecodeOctets([]byte{byte(v.Data)}), false))
}

// Report whether the octet is a symbol on its own (`0x00`–`0x7F`).
//
//kavun:member is_ascii pure () -> bool
func byteIsASCII(_ VM, v Value, id member.ID, args []Value) (Value, error) {
	return BoolValue(byte(v.Data) < 0x80), nil
}
